def solve(inp):
    A=np.array(inp); H,W=A.shape
    out=A.copy()
    changed=True
    seen_z=set()
    while changed:
        changed=False
        for r in range(H):
            for c in range(W):
                if out[r][c]!=0: continue
                rowv=[A[r][cc] for cc in range(W) if A[r][cc]!=0]
                colv=[A[rr][c] for rr in range(H) if A[rr][c]!=0]
                cands=set()
                for vals,name in ([rowv,'row'],[colv,'col']):
                    ps=periods(vals)
                    for p in ps:
                        m={}
                        okc=True
                        for idx,vv in enumerate(vals):
                            key=idx%p
                            if key in m and m[key]!=vv: okc=False;break
                            m[key]=vv
                        if not okc: continue
                        key=c%(p if name=='row' else 0) if name=='row' else r%p
                        if name=='row': key=c%p
                        else: key=r%p
                        if key in m: cands.add(m[key])
                if len(cands)==1:
                    out[r][c]=cands.pop(); changed=True
    return out.tolist()

